    signal?.addEventListener('abort',abort,{once:true});engine.onmessage=({data})=>finish(data.error?new Error(data.error):null,data);engine.onerror=()=>finish(new Error('보고서 처리 엔진을 확인하세요.'));engine.postMessage(message,message.bytes instanceof ArrayBuffer?[message.bytes]:[]);
