            const action={pwv:'inspect-powerview',bmt:'inspect-thermal-bmt',xlsx:'read-input-tables',csv:'read-input-tables'}[material.format];if(action){const result=await worker({action,bytes:await blob.arrayBuffer(),filename:material.filename},controller.signal);if(alive)setData(result);}else if(material.format!=='pdf'){if(alive)setData({text:'원본 파일을 내려받아 확인하세요.'});}
