    const exportCollection=()=>run('빈 한글 조사 양식 저장',async signal=>{const context=currentDraftContext(),{collectionFile}=await worker({action:'export-draft-collection',bytes:await(await loadMaterial(userId,material.id)).arrayBuffer(),context},signal);if(signal.aborted)return;download(new Blob([collectionFile.bytes],{type:'application/hwp+zip'}),`${material.filename.replace(/\.[^.]+$/,'')}-빈조사양식.hwpx`);change(current=>({...current,collectionExports:[...(current.collectionExports||[]),{sourceMaterialId:material.id,sourceSha256:material.sha256,schemaFingerprint:collectionFile.schemaFingerprint,fieldCount:collectionFile.fieldCount,createdAt:new Date().toISOString()}]}));setNotice('표의 검토된 라벨은 유지하고 입력·제외 칸을 비운 한글 조사 양식을 저장했습니다. 작성 후 이 화면에서 가져오세요.');});
